package com.example.complaintmanagement.service; import com.example.complaintmanagement.entity.User; import com.example.complaintmanagement.repository.UserRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; @Service public class CurrentUserService { private final UserRepository r; public CurrentUserService(UserRepository r){this.r=r;} public User get(){String u=SecurityContextHolder.getContext().getAuthentication().getName();return r.findByUsername(u).orElseThrow();} }